<?php $lista=$datosVista['listado'];$f=$datosVista['filtros'];$roles=$datosVista['roles'];$camaras=$datosVista['camaras'];$afiliados=$datosVista['afiliados'];$stats=$datosVista['estadisticas']; ?>
<section aria-labelledby="titulo-usuarios">
 <div data-panel-motion="title" class="mb-6"><h2 id="titulo-usuarios" class="text-2xl font-semibold text-foreground">Gestión de usuarios</h2><p class="mt-1 text-sm text-muted-foreground">Controla los accesos al panel y vincula los perfiles de afiliado con sus empresas.</p></div>
 <div class="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><?php foreach([['Total','total','ki-user-square','primary'],['Activos','activos','ki-shield-tick','success'],['Inactivos','inactivos','ki-information-2','danger'],['Perfiles','perfiles','ki-security-user','info']] as [$titulo,$campo,$icono,$color]): ?><article data-panel-motion="stat" class="kt-card canaco-stat-card"><div class="kt-card-body p-5"><span class="text-sm text-muted-foreground"><?= $titulo ?></span><div class="flex items-end justify-between mt-2"><strong class="text-3xl text-foreground"><?= (int)($stats[$campo]??0) ?></strong><span class="canaco-stat-icon bg-<?= $color ?>/10 text-<?= $color ?>"><i class="ki-filled <?= $icono ?>"></i></span></div></div></article><?php endforeach; ?></div>
 <div class="kt-card"><div data-panel-motion="tools" class="kt-card-header block py-4 min-h-0"><div class="canaco-directory-toolbar"><div><h3 class="font-semibold text-foreground">Usuarios registrados</h3><p class="text-sm text-muted-foreground">Los usuarios inactivos se conservan para mantener la trazabilidad.</p></div><button class="kt-btn kt-btn-primary shrink-0" type="button" id="btnNuevoUsuario"><i class="ki-filled ki-plus"></i>Registrar usuario</button></div><form class="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-4 gap-3 mt-4" method="get" action="<?= base_url('usuarios') ?>" role="search"><label class="kt-input"><i class="ki-filled ki-magnifier"></i><input type="search" name="q" value="<?= e($f['q']) ?>" placeholder="Nombre o correo"></label><select class="kt-select" name="rol"><option value="">Todos los perfiles</option><?php foreach($roles as $rol): ?><option value="<?= (int)$rol['idRol'] ?>" <?= (int)$f['rol']===(int)$rol['idRol']?'selected':'' ?>><?= e($rol['nombre']) ?></option><?php endforeach; ?></select><select class="kt-select" name="estado"><option value="">Todos los estados</option><option value="1" <?= $f['estado']==='1'?'selected':'' ?>>Activos</option><option value="0" <?= $f['estado']==='0'?'selected':'' ?>>Inactivos</option></select><button class="kt-btn kt-btn-light" type="submit">Filtrar</button></form></div>
 <div data-panel-motion="results" class="overflow-x-auto"><table class="kt-table canaco-table"><thead><tr><th>Usuario</th><th>Perfil y asignación</th><th>Último acceso</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($lista['registros'] as $usuario): ?><tr><td><div class="flex items-center gap-3"><span class="canaco-avatar"><i class="ki-filled ki-user-square"></i></span><div><div class="font-medium text-foreground"><?= e($usuario['nombre']) ?></div><div class="text-xs text-muted-foreground"><?= e($usuario['correo']) ?></div></div></div></td><td><div class="font-medium text-sm"><?= e($usuario['rol_nombre']) ?></div><div class="text-xs text-muted-foreground"><?= e($usuario['camara_nombre'] ?: ($usuario['afiliados_nombres'] ?: 'Sin asignación')) ?></div></td><td class="text-sm text-muted-foreground"><?= $usuario['ultimo_acceso_at'] ? e(date('d/m/Y H:i',strtotime($usuario['ultimo_acceso_at']))) : 'Sin accesos registrados' ?></td><td><span class="kt-badge kt-badge-outline <?= (int)$usuario['activo']?'kt-badge-success':'kt-badge-danger' ?>"><?= (int)$usuario['activo']?'Activo':'Inactivo' ?></span></td><td class="text-end whitespace-nowrap"><button class="kt-btn kt-btn-sm kt-btn-icon kt-btn-ghost btn-editar-usuario" type="button" data-id="<?= (int)$usuario['idUsuario'] ?>" aria-label="Editar <?= e($usuario['nombre']) ?>" title="Editar"><i class="ki-filled ki-pencil"></i></button><button class="kt-btn kt-btn-sm kt-btn-icon kt-btn-ghost btn-estado-usuario" type="button" data-id="<?= (int)$usuario['idUsuario'] ?>" data-activo="<?= (int)$usuario['activo']?'0':'1' ?>" data-nombre="<?= e($usuario['nombre']) ?>" aria-label="Cambiar estado de <?= e($usuario['nombre']) ?>" title="Cambiar estado"><i class="ki-filled <?= (int)$usuario['activo']?'ki-toggle-on-circle':'ki-toggle-off-circle' ?>"></i></button></td></tr><?php endforeach; ?><?php if(!$lista['registros']): ?><tr><td colspan="5"><div class="canaco-empty"><span class="canaco-empty-icon"><i class="ki-filled ki-user-square"></i></span><strong>No hay usuarios</strong><p>Registra el primer usuario para el panel administrativo.</p></div></td></tr><?php endif; ?></tbody></table></div><div class="kt-card-footer py-4"><span class="text-sm text-muted-foreground"><?= (int)$lista['total'] ?> resultado<?= (int)$lista['total']===1?'':'s' ?></span></div></div>
</section>
<div class="canaco-modal" id="modalUsuario" hidden aria-hidden="true"><div class="canaco-modal-backdrop" data-usuario-close></div><div class="canaco-modal-dialog max-w-3xl" role="dialog" aria-modal="true" aria-labelledby="tituloModalUsuario"><form id="formUsuario" novalidate><input type="hidden" name="csrf_token" value="<?= e(obtenerTokenCSRF()) ?>"><input type="hidden" name="idUsuario"><div class="canaco-modal-header"><div><h3 id="tituloModalUsuario" class="text-lg font-semibold">Registrar usuario</h3><p class="text-sm text-muted-foreground mt-1">Los campos con * son obligatorios.</p></div><button type="button" class="kt-btn kt-btn-icon kt-btn-ghost" data-usuario-close aria-label="Cerrar"><i class="ki-filled ki-cross"></i></button></div><div class="canaco-modal-body"><div class="grid grid-cols-1 md:grid-cols-2 gap-5"><div class="canaco-field"><label for="usuarioNombre">Nombre *</label><input class="kt-input" id="usuarioNombre" name="nombre" maxlength="150" autocomplete="name"><span data-error="nombre"></span></div><div class="canaco-field"><label for="usuarioCorreo">Correo electrónico *</label><input class="kt-input" id="usuarioCorreo" name="correo" type="email" maxlength="254" autocomplete="email"><span data-error="correo"></span></div><div class="canaco-field"><label for="usuarioRol">Perfil *</label><select class="kt-select" id="usuarioRol" name="idRol"><option value="">Selecciona un perfil</option><?php foreach($roles as $rol): ?><option value="<?= (int)$rol['idRol'] ?>" data-clave="<?= e($rol['clave']) ?>"><?= e($rol['nombre']) ?></option><?php endforeach; ?></select><span data-error="idRol"></span></div><div class="canaco-field"><label for="usuarioActivo">Estatus *</label><select class="kt-select" id="usuarioActivo" name="activo"><option value="1">Activo</option><option value="0">Inactivo</option></select></div></div><div class="grid grid-cols-1 md:grid-cols-2 gap-5 mt-5"><div class="canaco-field"><label for="usuarioPassword">Contraseña <span id="textoPassword">*</span></label><input class="kt-input" id="usuarioPassword" name="password" type="password" minlength="10" autocomplete="new-password"><small id="ayudaPassword">Mínimo 10 caracteres, incluyendo letras y números.</small><span data-error="password"></span></div><div class="canaco-field"><label for="usuarioPasswordConfirmacion">Confirmar contraseña <span id="textoPasswordConfirmacion">*</span></label><input class="kt-input" id="usuarioPasswordConfirmacion" name="password_confirmacion" type="password" minlength="10" autocomplete="new-password"><span data-error="password_confirmacion"></span></div></div><div class="canaco-field mt-5" id="grupoCamara" hidden><label for="usuarioCamara">Cámara asignada *</label><select class="kt-select" id="usuarioCamara" name="idCamara"><option value="">Selecciona una cámara</option><?php foreach($camaras as $camara): ?><option value="<?= (int)$camara['idCamara'] ?>"><?= e($camara['nombre']) ?></option><?php endforeach; ?></select><small>Este administrador solo podrá gestionar los afiliados de esta cámara.</small><span data-error="idCamara"></span></div><fieldset class="canaco-field mt-5" id="grupoAfiliados" hidden><legend class="text-sm font-medium text-foreground">Afiliados vinculados *</legend><p class="text-sm text-muted-foreground">Este perfil podrá administrar únicamente las empresas seleccionadas.</p><div class="canaco-category-list mt-3" id="listaAfiliados"><?php foreach($afiliados as $afiliado): ?><label><input class="kt-checkbox kt-checkbox-sm" type="checkbox" name="afiliados[]" value="<?= (int)$afiliado['idAfiliado'] ?>"><span><?= e($afiliado['nombre_comercial']) ?></span></label><?php endforeach; ?></div><span data-error="afiliados"></span></fieldset></div><div class="canaco-modal-footer"><button type="button" class="kt-btn kt-btn-light" data-usuario-close>Cancelar</button><button type="submit" class="kt-btn kt-btn-primary" id="btnGuardarUsuario"><span>Guardar usuario</span></button></div></form></div></div>
<div class="canaco-toast" id="notificacionUsuario" role="status" aria-live="polite" hidden></div>
